import { useSelector } from 'react-redux';
import { Button } from '@mui/material';
import ListItem from '../../../../layout/MenuList/ListItem/ListItem';
import ListCollapse from '../../../../layout/MenuList/ListCollapse/ListCollapse';
import useUserSidebar from './useUserSidebar';
import '../../../../styles/components/Sidebar.css';

export default function Sidebar() {
    const { user } = useSelector((state) => state.auth);

    const {
        mainTabs,
        isItemSelected,
        selectedItems,
        settingTabs
    } = useUserSidebar();

    return (
        <aside id="event-dashboard-sidebar">
            <div className="go-back-container">
                <Button
                    fullWidth
                    size="large"
                    variant="text"
                    sx={{ ...backBtnStyle, cursor: 'default' }}
                    disableRipple
                >
                    Hi, {user?.name || 'User'}
                </Button>
            </div>
            <div className="event-dashboard-tabs-container">
                <div className="event-dashboard-main-tabs">
                    {mainTabs.map((item) => {
                        if (item.type === 'item') {
                            return (
                                <ListItem
                                    key={item.id}
                                    tabName={item.title}
                                    icon={item.icon}
                                    url={item.url}
                                    isSelected={isItemSelected(item)}
                                    shouldEnabledMenu={!item.enabled}
                                />
                            );
                        } else if (item.type === 'collapse') {
                            const hasEnabledChild = !item.children.some(
                                (child) => child.enabled
                            );
                            return (
                                <ListCollapse
                                    key={item.id}
                                    tabName={item.title}
                                    icon={item.icon}
                                    children={item.children}
                                    selectedChildUrl={selectedItems.childSelectedUrl}
                                    shouldEnabledMenu={hasEnabledChild}
                                />
                            );
                        }
                        return null;
                    })}
                </div>
                <div className="event-settings-log-out-tabs">
                    <div className="event-setting-tabs">
                        {settingTabs.map((item) => (
                            <ListItem
                                key={item.id}
                                tabName={item.title}
                                icon={item.icon}
                                url={item.url}
                                isSelected={item.id === selectedItems.settingSelected}
                                shouldEnabledMenu={!item.enabled}
                            />
                        ))}
                    </div>
                </div>
            </div>
        </aside>
    );
}

const backBtnStyle = {
    color: 'var(--quaternary-color)',
    textTransform: 'capitalize',
    fontFamily: 'Nunito, sans-serif',
    fontSize: '1.25rem',
    justifyContent: 'flex-start',
    borderRadius: '0.625rem'
};