import { useMemo } from "react";
import { useLocation } from "react-router-dom";
import {
    Dashboard,
    EditCalendar,
    EventAvailable,
    Summarize,
    Help,
    Settings
} from '@mui/icons-material';

export default function useUserSidebar() {
    const location = useLocation();
    const currentPath = location.pathname;


    /**
     * User Dashboard Menus List
     */
    const userDashboardMenusList = [
        {
            id: 'userDashboard',
            title: 'Dashboard',
            type: 'item',
            icon: <Dashboard />,
            url: '/user/dashboard',
            enabled: true
        },
        {
            id: 'myBookings',
            title: 'My Bookings',
            type: 'collapse',
            icon: <EditCalendar />,
            children: [
                {
                    id: 'eventBookings',
                    title: 'Event Bookings',
                    type: 'item',
                    url: '/user/event-bookings',
                    enabled: true
                },
                // {
                //     id: 'venueBookings',
                //     title: 'Venue Bookings',
                //     type: 'item',
                //     url: '/user/venue-bookings'
                // }
            ]
        },
        {
            id: 'myEvents',
            title: 'My Events',
            type: 'item',
            icon: <EventAvailable />,
            url: '/user/my-events',
            enabled: true
        },
        {
            id: 'eventReports',
            title: 'Event Reports',
            type: 'item',
            icon: <Summarize />,
            url: '/user/event-reports',
            enabled: true
        },
        {
            id: 'helpAndSupport',
            title: 'Help & Support',
            type: 'item',
            icon: <Help />,
            url: '/user/help-and-support',
            enabled: true
        },
        {
            id: 'settings',
            title: 'Settings',
            type: 'item',
            icon: <Settings />,
            url: '/user/settings',
            enabled: true
        }
    ];


    /**
     * Main and Settings Tabs
     */
    const mainTabs = userDashboardMenusList.filter(
        (item) => !['settings', 'helpAndSupport'].includes(item.id)
    );

    const settingTabs = userDashboardMenusList.filter((item) =>
        ['helpAndSupport', 'settings'].includes(item.id)
    );


    /**
     * Select the current selected items based on the current path
     * @returns Object with mainSelected, settingSelected and childSelectedUrl
     */
    const selectedItems = useMemo(() => {
        // Find if the current path matched any of in the main tabs
        const mainSelected = mainTabs.find(
            (item) =>
                item.url === currentPath ||
                (item.children && item.children.some((child) => child.url === currentPath))
        );

        // Find if the current path matched any of in the setting tabs
        const settingSelected = settingTabs.find((item) => item.url === currentPath);

        return {
            mainSelected: mainSelected?.id || '',
            settingSelected: settingSelected?.id || '',
            childSelectedUrl: currentPath
        };
    }, [currentPath]);


    /**
     * Check if the item is selected
     * @param {Object} item - Menu item
     * @returns {Boolean} - true if selected, false otherwise
     */
    const isItemSelected = (item) => {
        if (item.type === 'item') {
            return item.url === selectedItems.childSelectedUrl;
        } else if (item.type === 'collapse') {
            return item.id === selectedItems.mainSelected;
        } else if (item.id === 'settings') {
            return item.id === selectedItems.settingSelected;
        }
        return false;
    };

    return {
        mainTabs,
        settingTabs,
        isItemSelected,
        selectedItems
    };
}